{
  "part": {
    "name": "Rounded-head lever arm with end mounting bore and clearance pocket",
    "description": "Single-solid prismatic lever/handle-like component with a large rounded head at one end, a long rectangular arm, a right-end mounting face with a blind cylindrical bore, and a rectangular clearance pocket cut into the arm. External edges are heavily radiused/filleted with a mix of cylindrical, spherical, conical, and spline blend faces.",
    "source_views": [
      "front",
      "back",
      "left",
      "right",
      "top",
      "bottom",
      "toprightiso"
    ],
    "symmetry_note": "Overall outer form is approximately symmetric about a longitudinal mid-plane for much of the arm, but symmetry is broken by the clearance pocket and local end blends/chamfers."
  },
